d = ""
print("Original sequence", d)

r_d = "".join(reversed(d))
print("Reversed sequence", r_d)

def compliment(r_d):
    chargaff = {"A":"T", "G":"C", "T":"A", "C":"G"}  
    x = "" 
    for base in r_d:
        x = x + ''.join(chargaff[base])
    return x

print("Compliment of Reversed sequence", compliment(r_d))